import type { CSSProperties, HTMLAttributes, ReactNode } from "react";
import "./glass-plate.css";

export interface GlassPlateProps extends HTMLAttributes<HTMLDivElement> {
  /** 宽高给数按 px，给字符串原样用（"100%"、"68px"）。 */
  width?: number | string;
  height?: number | string;
  /** 圆角，按 px。 */
  radius?: number;
  /** 板子有多实：0 基本全透、只剩一层雾，1 近乎实底。 */
  frost?: number;
  /** 透上来的颜色有多艳（背后那层颜色的饱和度）。 */
  saturation?: number;
  children?: ReactNode;
}

const measure = (value: number | string | undefined, fallback: string) =>
  value === undefined
    ? fallback
    : typeof value === "number"
      ? `${value}px`
      : value;

/**
 * 一块玻璃板：雾面的底、斜着扫过的一道高光、上沿一线亮边，透过它看得见
 * 背后的颜色。宽高圆角由调用方给，颜色跟着主题走（--theme-panel / -line /
 * --theme-shadow），所以换肤自动换这块玻璃。
 *
 * 只有两层伪元素，没有脚本：不量尺寸、不挂观察器、不生成滤镜。背后模糊
 * 由 backdrop-filter 直接做，浏览器不支持时把板子调实一点压住（`.glass-plate`
 * 末尾的 @supports），文字照样读得清。
 */
export function GlassPlate({
  children,
  width = "100%",
  height = 80,
  radius = 20,
  frost = 0.5,
  saturation = 1.2,
  className = "",
  style,
  ...rest
}: GlassPlateProps) {
  return (
    <div
      className={["glass-plate", className].filter(Boolean).join(" ")}
      style={
        {
          width: measure(width, "100%"),
          height: measure(height, "80px"),
          borderRadius: `${radius}px`,
          "--plate-frost": frost,
          "--plate-saturation": saturation,
          ...style,
        } as CSSProperties
      }
      {...rest}
    >
      <div className="glass-plate__content">{children}</div>
    </div>
  );
}

export default GlassPlate;
