import { type CSSProperties, useState } from "react";
import { Bell, BellRing } from "lucide-react";
import { cn } from "../../lib/cn";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./bookmark-bell.css";

export type BookmarkBellSize = "sm" | "md";

export interface BookmarkBellProps {
  /** 没收藏时铃铛旁边那两个字。 */
  offLabel?: string;
  /** 收藏之后换成它。 */
  onLabel?: string;
  /** 受控：听外面说现在收没收藏。 */
  pressed?: boolean;
  defaultPressed?: boolean;
  onChange?: (pressed: boolean) => void;
  disabled?: boolean;
  size?: BookmarkBellSize;
  color?: string;
  background?: string;
  onColor?: string;
  onBackground?: string;
  /** 读屏软件的称呼；不给就用没收藏时那个标签。 */
  ariaLabel?: string;
  className?: string;
}

/** 三档高度：高度、字号、铃铛大小一起跟着走。 */
const SIZE_TOKENS: Record<BookmarkBellSize, [number, number, number, number]> = {
  sm: [32, 12.5, 14, 13],
  md: [40, 13.5, 16, 16],
};

/**
 * 收藏铃：一颗会响的收藏按钮。
 *
 * 藏了两种说法（收藏 / 已收藏），两行叠在同一格里轮流露面，所以换字的时候
 * 按钮宽度一动不动 —— 不需要先去量谁宽谁窄。按下时整颗缩小一点，点「开」
 * 的那一下铃身左右摆动、铃口再荡出一圈光环：都是 CSS 关键帧，动画结束就
 * 停在原地，不必收尾。减少动效时只留颜色变化，不摆不荡。
 */
export function BookmarkBell({
  offLabel = "收藏",
  onLabel = "已收藏",
  pressed,
  defaultPressed = false,
  onChange,
  disabled = false,
  size = "md",
  color = "#f5f5f5",
  background = "#27272a",
  onColor = "#18181b",
  onBackground = "#f5f5f5",
  ariaLabel,
  className = "",
}: BookmarkBellProps) {
  const [inner, setInner] = useState(defaultPressed);
  const on = pressed ?? inner;
  const reduce = usePrefersReducedMotion();
  /** 每响一次加一 —— 当成 key 挂给铃铛，节点换新，关键帧从头再放一遍。 */
  const [ringKey, setRingKey] = useState(0);
  const [height, fontSize, iconSize, gap] = SIZE_TOKENS[size] ?? SIZE_TOKENS.md;

  const toggle = () => {
    if (disabled) return;
    const next = !on;
    if (pressed === undefined) setInner(next);
    onChange?.(next);
    if (next && !reduce) setRingKey((value) => value + 1);
  };

  return (
    <button
      type="button"
      className={cn("bookmark-bell", className)}
      data-on={on ? "" : undefined}
      aria-pressed={on}
      aria-label={ariaLabel ?? offLabel}
      disabled={disabled}
      onClick={toggle}
      style={
        {
          "--bb-ink": color,
          "--bb-bg": background,
          "--bb-on-ink": onColor,
          "--bb-on-bg": onBackground,
          "--bb-h": `${height}px`,
          "--bb-fs": `${fontSize}px`,
          "--bb-icon": `${iconSize}px`,
          "--bb-gap": `${gap}px`,
        } as CSSProperties
      }
    >
      {/* key 换新 = 铃铛重新挂一次，摆动和光环都从头来 */}
      <span
        className="bookmark-bell__glyph"
        key={ringKey}
        data-ring={ringKey > 0 ? "" : undefined}
        aria-hidden="true"
      >
        {on ? (
          <BellRing size={iconSize} strokeWidth={2} />
        ) : (
          <Bell size={iconSize} strokeWidth={2} />
        )}
        {ringKey > 0 ? <span className="bookmark-bell__halo" /> : null}
      </span>
      <span className="bookmark-bell__say" aria-hidden="true">
        <span className="bookmark-bell__word bookmark-bell__word--off">
          {offLabel}
        </span>
        <span className="bookmark-bell__word bookmark-bell__word--on">
          {onLabel}
        </span>
      </span>
    </button>
  );
}

export default BookmarkBell;
