import { type CSSProperties, useState } from "react";
import { cn } from "../../lib/cn";
import "./mastery-check.css";

export interface MasteryCheckProps {
  label: string;
  /** 受控：现在勾没勾上。 */
  checked?: boolean;
  defaultChecked?: boolean;
  onChange?: (checked: boolean) => void;
  disabled?: boolean;
  /** 框线和字的颜色。 */
  color?: string;
  /** 勾上之后填进框里的那层颜色。 */
  fillColor?: string;
  /** 勾本身（画在填充上面）的颜色。 */
  checkColor?: string;
  fontSize?: number;
  className?: string;
}

/** 勾自己画：一条两折的线，配 pathLength=1 好让描边一笔一笔走出来。 */
const TICK_PATH = "M5.5 12.6 10.2 17.2 18.5 7.4";

/**
 * 掌握勾：「这个表达我拿下了」那一行。
 *
 * 一条带方框的整行按钮，role 就是 checkbox。勾上那一下，色块从框心弹开
 * （带一点过冲）、勾跟着描出来、字慢慢退成灰的、再压一条横线过去 ——
 * 四件事各有各的节拍，用 CSS 变量统一从外面调色。取消时收得快一些，
 * 不留拖泥带水。减少动效时全部一步到位。
 */
export function MasteryCheck({
  label,
  checked,
  defaultChecked = false,
  onChange,
  disabled = false,
  color = "#ffffff",
  fillColor = "#ffffff",
  checkColor = "#0b0b0f",
  fontSize = 18,
  className = "",
}: MasteryCheckProps) {
  const [inner, setInner] = useState(defaultChecked);
  const on = checked ?? inner;

  const toggle = () => {
    if (disabled) return;
    const next = !on;
    if (checked === undefined) setInner(next);
    onChange?.(next);
  };

  // 框、勾、字号都跟着字号走，行高保证指头点得到。
  const box = Math.round(fontSize * 1.5);
  const tick = Math.round(box * 0.62);

  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={on}
      className={cn("mastery-check", className)}
      data-on={on ? "" : undefined}
      disabled={disabled}
      onClick={toggle}
      style={
        {
          "--mc-ink": color,
          "--mc-fill": fillColor,
          "--mc-tick": checkColor,
          "--mc-font": `${fontSize}px`,
          "--mc-box": `${box}px`,
          "--mc-tick-size": `${tick}px`,
        } as CSSProperties
      }
    >
      <span className="mastery-check__box" aria-hidden="true">
        <span className="mastery-check__fill" />
        <svg className="mastery-check__pen" viewBox="0 0 24 24" aria-hidden="true">
          <path
            d={TICK_PATH}
            pathLength={1}
            fill="none"
            stroke="var(--mc-tick)"
            strokeWidth={2.6}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </span>
      <span className="mastery-check__word">
        {label}
        <span className="mastery-check__strike" aria-hidden="true" />
      </span>
    </button>
  );
}

export default MasteryCheck;
